import React from "react";
import BigBangImage from "./bigBang.png";

function Section2() {
  return (
   <>
   <div className=" h-1/2 w-full justify-center flex mt-10 ">
    <div className=" w-1/6 h-1/2 border  border-white rounded-xl">
    <img src={BigBangImage} alt="Big Bang Image" className=" rounded-xl m-1"  />
    <div className=" justify-center flex">

    <h1 className=" text-yellow-500 relative">Formation and Early Evolution</h1>
    </div>
    </div>
   </div>
   </>
  );
}

export default Section2;
